public class Diferencias {
  public static void main(String[] args) {
      int[] arr = {10, 15, 25, 5};
      // El array resultante será 1 elemento más pequeño que el original
      int[] newarr = new int[arr.length - 1];

      // Diferencia discreta (N - N-1) en código Java manual:
      for (int i = 1; i < arr.length; i++) {
          newarr[i-1] = arr[i] - arr[i-1];
      }

      System.out.println(java.util.Arrays.toString(newarr));
  }
}
